// Media helpers, resolve manifest entries generated by scripts/optimize-images.mjs
// into <picture>-ready data. Keeps every page free of hardcoded file paths.
import manifest from '../data/media-manifest.json';
import { href } from './url.js';

const BASE = '/media/img';

export function imageEntry(name) {
  const entry = manifest[name];
  if (!entry) {
    throw new Error(`[media] No manifest entry for image "${name}". Run: npm run assets:images`);
  }
  return entry;
}

function srcset(name, ext, widths) {
  return widths.map((w) => `${href(`${BASE}/${name}-${w}.${ext}`)} ${w}w`).join(', ');
}

/**
 * Build everything <Picture> needs for one manifest image.
 * @param {string} name manifest key, e.g. 'beef-biryani'
 */
export function pictureFor(name) {
  const e = imageEntry(name);
  const fallbackWidth = e.widths[Math.min(1, e.widths.length - 1)];
  return {
    avif: srcset(name, 'avif', e.widths),
    webp: srcset(name, 'webp', e.widths),
    jpeg: srcset(name, 'jpg', e.widths),
    fallback: href(`${BASE}/${name}-${fallbackWidth}.jpg`),
    width: e.width,
    height: e.height,
    aspect: e.aspect,
    placeholder: e.placeholder,
  };
}

export function videoFor(name) {
  return {
    src: href(`/media/video/${name}.mp4`),
    poster: href(`/media/video/${name}-poster.jpg`),
    posterWebp: href(`/media/video/${name}-poster.webp`),
  };
}

export const logo = manifest.logo; // { background: '#194220', hasAlpha: false, ... }
